const tools: Anthropic.Tool[] = [{
  name: 'get_weather',
  description: 'Vremea curentă într-un oraș',
  input_schema: { type: 'object', properties: { city: { type: 'string' } }, required: ['city'] },
}]
const messages: Anthropic.MessageParam[] = [{ role: 'user', content: 'Plouă în Cluj?' }]
const res = await client.messages.create({ model: 'claude-opus-5', max_tokens: 16000, tools, messages })
if (res.stop_reason === 'tool_use') {
  messages.push({ role: 'assistant', content: res.content })
  const results: Anthropic.ToolResultBlockParam[] = []
  for (const b of res.content)
    if (b.type === 'tool_use') results.push({ type: 'tool_result', tool_use_id: b.id, content: await getWeather(b.input) })
  messages.push({ role: 'user', content: results }) // apoi încă un create(): modelul scrie răspunsul
}
